const categories=[['all','✳','All opportunities'],['produce','🥬','Farm produce'],['buyers','🤝','Buyers'],['transport','🚚','Transport'],['supplies','🌱','Fertilizer'],['equipment','🚜','Farm equipment'],['land','🌾','Agricultural land'],['export','🌍','Export connections']];
