const samples=[{id:'s1',category:'produce',title:'Fresh harvest, straight from the farm',owner:'Sample farmer · Produce seller',district:'Nuwara Eliya',price:'LKR 280 / kg · sample price',description:'Sample wholesale listing: 2,000 kg of fresh carrots available, minimum order 500 kg. Discuss harvest dates, quantity and collection directly with the farmer.',icon:'🥕',color:'#e8c6a2'},{id:'s2',category:'transport',title:'Make the journey to market easier',owner:'Sample transport provider',district:'Matale',price:'Request a quote',description:'Sample transport service for farm produce. Enquire about route, vehicle capacity, collection date and handling requirements.',icon:'🚚',color:'#d8ddbf'},{id:'s3',category:'supplies',title:'Organic compost for your next season',owner:'Sample fertilizer supplier',district:'Kurunegala',price:'LKR 1,200 / bag · sample price',description:'Sample wholesale supplier listing: minimum order 50 bags of 25 kg compost. Confirm product details, availability and delivery arrangements with the supplier.',icon:'🌱',color:'#cad9bc'},{id:'s4',category:'land',title:'Room for your next growing chapter',owner:'Sample land seller',district:'Anuradhapura',price:'Contact for terms',description:'Sample agricultural land listing. Enquire about acreage, water access, ownership documents and viewing arrangements.',icon:'🌾',color:'#e0d5ae'},{id:'s5',category:'export',title:'Connecting local harvests to new markets',owner:'Sample exporter',district:'Colombo',price:'Discuss supply requirements',description:'Sample exporter seeking conversations with growers. Discuss crop type, quality specifications, volumes and delivery schedules.',icon:'🌍',color:'#bfd4cc'},{id:'s6',category:'buyers',title:'A buyer for your next rice harvest',owner:'Sample produce buyer',district:'Polonnaruwa',price:'Enquire for buying terms',description:'Sample buyer enquiry for paddy. Share variety, expected quantity and harvest date to start a conversation.',icon:'🌾',color:'#eadbbd'}];
for(const listing of samples){listing.intent=['s5','s6'].includes(listing.id)?'request':'offer';listing.authorRole=({'s1':'Farmer','s2':'Transport provider','s3':'Fertilizer supplier','s4':'Land seller','s5':'Exporter','s6':'Wholesale buyer'})[listing.id]}
