const $=s=>document.querySelector(s);const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageAvailable=true;function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}const stored=read('fd-preview-v1',{})||{};let state={listings:Array.isArray(stored.listings)?stored.listings:[],saved:Array.isArray(stored.saved)?stored.saved:[],enquiries:Array.isArray(stored.enquiries)?stored.enquiries:[]};state.bids=Array.isArray(stored.bids)?stored.bids:[];let view='all',category='all';
let profiles=read('fd-profiles-v1',[]);if(!Array.isArray(profiles))profiles=[];let currentProfileId=null;let pendingListing=false;function currentProfile(){return profiles.find(p=>p.id===currentProfileId)||null}
let feedScope='recommended';let pendingImages=[];let processingImages=false;
const roleViews={Farmer:['Your farming business','Find wholesale buyers, transport, fertilizer, land and export connections.'],'Wholesale buyer':['Find wholesale farm produce','Discover farmers offering harvests for bulk purchase.'],'Transport provider':['Transport jobs from farmers','See farmers requesting transport for their harvests and supplies.'],'Fertilizer supplier':['Your fertilizer business','Manage your products and offers, and respond to farmers needing fertilizer.'],'Land seller':['Land requests from farmers','See farmers looking for agricultural land.'],'Equipment seller':['Equipment requests from farmers','Find farmers looking for agricultural machinery and equipment.'],Exporter:['Source produce from farmers','Connect with farmers offering produce for wholesale export supply.']};
function relevantToRole(listing,profile){if(!profile)return true;if(listing.profileId===profile.id)return profile.role==='Fertilizer supplier'&&listing.category==='supplies'&&listing.intent==='offer';const intent=listing.intent||'offer';if(profile.role==='Farmer')return (['buyers','export'].includes(listing.category)&&intent==='request')||(['transport','supplies','land','equipment'].includes(listing.category)&&intent==='offer');if(['Wholesale buyer','Exporter'].includes(profile.role))return listing.category==='produce'&&intent==='offer'&&listing.authorRole==='Farmer';if(profile.role==='Transport provider'&&listing.category==='produce'&&intent==='offer'&&listing.authorRole==='Farmer')return true;const categoryByRole={'Transport provider':'transport','Fertilizer supplier':'supplies','Land seller':'land','Equipment seller':'equipment'};return listing.category===categoryByRole[profile.role]&&intent==='request'&&listing.authorRole==='Farmer'}
function updatePerspective(){const profile=currentProfile(),copy=profile?roleViews[profile.role]:['A marketplace built around farmers','Register to see opportunities matched to your role.'];$('#perspective-title').textContent=copy[0];$('#perspective-description').textContent=copy[1];$('#feed-scope').hidden=!profile;$('#feed-scope').value=feedScope;$('#catalog-scope').hidden=profile?.role!=='Fertilizer supplier';$('#role-label').textContent=profile?profile.role:'Guest'}
function persist(){try{localStorage.setItem('fd-preview-v1',JSON.stringify(state));return true}catch{storageAvailable=false;toast('Browser storage is full or unavailable. This change could not be saved.');return false}}function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}function all(){return [...state.listings.filter(x=>x.wholesale===true&&x.profileId),...samples]}function label(c){return categories.find(x=>x[0]===c)?.[2]||c}function option(value){return `<option value="${safe(value)}">${safe(value)}</option>`}
$('#categories').innerHTML=categories.map(([id,icon,name])=>`<button class="category ${id==='all'?'selected':''}" data-category="${id}" aria-pressed="${id==='all'}"><span aria-hidden="true">${icon}</span><b>${name}</b></button>`).join('');
$('#register-district').innerHTML=districts.map(option).join('');
$('#district').insertAdjacentHTML('beforeend',districts.map(option).join(''));$('#form-district').innerHTML=districts.map(option).join('');$('#form-category').innerHTML=categories.slice(1).map(([id,,name])=>`<option value="${id}">${name}</option>`).join('');
function render(){window.renderDirectory?.();updateAccount();updatePerspective();$('#listing-price-note').hidden=!$('#sort').value.startsWith('price-');const query=$('#search').value.trim().toLowerCase(),district=$('#district').value;$('#saved-count').textContent=state.saved.length;$('#view-title').textContent=view==='saved'?'Your saved opportunities':view==='enquiries'?'Your enquiry drafts':(category==='all'?'Discover your next opportunity':label(category));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let rows=all().filter(x=>(view!=='all'||!currentProfile()||feedScope==='all'||(feedScope==='mine'?x.profileId===currentProfile().id:feedScope==='catalog'?x.profileId===currentProfile().id&&x.category==='supplies'&&x.intent==='offer':relevantToRole(x,currentProfile())))&&(view!=='saved'||state.saved.includes(x.id))&&(category==='all'||x.category===category)&&(!district||x.district===district)&&[x.title,x.owner,x.description,x.district,...[x.title,x.description,x.district].map(v=>window.fdTranslate?window.fdTranslate(v):v)].join(' ').toLowerCase().includes(query));if($('#sort').value==='title')rows.sort((a,b)=>a.title.localeCompare(b.title));else if(window.sortMarketplace)rows=window.sortMarketplace(rows,$('#sort').value);if(view==='enquiries'){const drafts=state.enquiries.filter(x=>{const listing=all().find(y=>y.id===x.listingId);return listing&&rows.some(y=>y.id===listing.id)});$('#grid').innerHTML=drafts.map(x=>`<article class="enquiry"><span class="badge">Local draft · Not sent</span><h3>${safe(all().find(y=>y.id===x.listingId).title)}</h3><p>${safe(x.message)}</p><button class="detail-button" data-remove="${safe(x.id)}">Delete draft</button></article>`).join('');$('#empty').hidden=!!drafts.length;$('#results').textContent=`${drafts.length} enquiry drafts`;return}const cardHtml=x=>`<article class="card"><div class="art" style="--art:${x.color}">${x.images?.length?`<img class="listing-cover" src="${safe(x.images[0])}" alt="${safe(x.title)}">`:`<span aria-hidden="true">${x.icon}</span>`}<button class="save" data-save="${safe(x.id)}" aria-label="${state.saved.includes(x.id)?'Unsave':'Save'} ${safe(x.title)}" aria-pressed="${state.saved.includes(x.id)}">${state.saved.includes(x.id)?'♥':'♡'}</button></div><div class="card-body"><span class="badge">${safe(label(x.category))}</span> <span class="badge">${x.intent==='request'?'Needed':'Offering'}</span><span class="location">${safe(x.district)}</span><h3>${safe(x.title)}</h3><p class="owner">${safe(x.owner)}</p>${x.category==='supplies'&&x.intent==='offer'?`<p class="muted">${x.catalogType==='offer'?'Fertilizer offer':'Fertilizer product'}</p>`:''}<p class="muted minimum">${safe(x.minimum||'Wholesale / business enquiry')}</p><div class="card-bottom"><strong>${safe(x.price)}</strong><button class="detail-button" data-detail="${safe(x.id)}">View ↗</button></div></div></article>`;$('#grid').innerHTML=category==='all'?categories.slice(1).map(([id,,name])=>{const sectionRows=rows.filter(x=>x.category===id);return sectionRows.length?`<section class="market-section" aria-label="${safe(name)}"><div class="section-heading"><h3>${safe(name)}</h3><button class="detail-button" data-category="${id}">Browse section ↗</button></div><div class="section-listings">${id==='supplies'?fertilizerGroups(sectionRows,cardHtml):sectionRows.map(cardHtml).join('')}</div></section>`:''}).join(''):category==='supplies'?fertilizerGroups(rows,cardHtml):rows.map(cardHtml).join('');$('#empty').hidden=!!rows.length;$('#results').textContent=`${rows.length} opportunities${view==='saved'?' saved':''}`}
document.addEventListener('click',event=>{const categoryButton=event.target.closest('[data-category]');if(categoryButton){window.openSection(categoryButton.dataset.category);return}const nav=event.target.closest('[data-view]');if(nav){window.clearSection?.();view=nav.dataset.view;render();$('#market').scrollIntoView({behavior:'smooth'})}const save=event.target.closest('[data-save]');if(save){const id=save.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render()}const detail=event.target.closest('[data-detail]');if(detail)showDetail(detail.dataset.detail);const remove=event.target.closest('[data-remove]');if(remove){state.enquiries=state.enquiries.filter(x=>x.id!==remove.dataset.remove);persist();render()}if(event.target.closest('.close'))event.target.closest('dialog').close()});
function showDetail(id){const x=all().find(y=>y.id===id);$('#detail-content').innerHTML=`<p class="eyebrow">${safe(label(x.category))} · ${safe(x.district)}</p><h2>${safe(x.title)}</h2><p class="muted">${safe(x.owner)}</p><h3 data-no-translate>${safe(x.price)}</h3>${listingFactsHtml(x)}<p><strong>Wholesale terms:</strong> ${safe(x.minimum||'Bulk supply or agricultural business enquiry — confirm terms with provider.')}</p>${x.category==='supplies'&&x.intent==='offer'?`<p><strong>Pack size</strong>: <span data-no-translate>${safe(x.packSize||'—')}</span></p>`:''}<p class="muted">${safe(x.description)}</p>${biddingHtml(x)}<form id="enquiry-form"><label>Your enquiry<textarea name="message" required maxlength="1500" rows="4" placeholder="Introduce yourself and ask about availability, quantity or terms."></textarea></label><p class="muted">Save a local draft. Messaging and verified accounts are not connected yet.</p><button class="primary">Save enquiry draft</button></form>`;$('#enquiry-form').onsubmit=e=>{e.preventDefault();state.enquiries.unshift({id:crypto.randomUUID(),listingId:id,message:new FormData(e.target).get('message').trim(),createdAt:new Date().toISOString()});const saved=persist();$('#detail').close();render();if(saved)toast('Enquiry draft saved on this device. Not sent.')};bindBidding(x);if(!$('#detail').open)$('#detail').showModal()}
for(const id of ['#post','#community-post'])$(id).onclick=requestListing;for(const id of ['#search','#district','#sort'])$(id).addEventListener(id==='#search'?'input':'change',render);
$('#listing-form').onsubmit=e=>{e.preventDefault();const profile=currentProfile();if(!profile){$('#listing-dialog').close();pendingListing=true;openAccount();return}if(processingImages){toast('Please wait for image processing.');return}if(!e.target.reportValidity())return;const fields=Object.fromEntries(new FormData(e.target));const error=validateListingFields(fields);if(error){toast(error);return}const listing={...fields,images:[...pendingImages],owner:profile.name,authorRole:profile.role,profileId:profile.id,wholesale:true,createdAt:new Date().toISOString(),id:crypto.randomUUID(),icon:categories.find(c=>c[0]===fields.category)[1],color:'#d5dfc6'};state.listings.unshift(listing);if(!persist()){state.listings=state.listings.filter(x=>x.id!==listing.id);return}e.target.reset();pendingImages=[];renderImagePreviews();$('#listing-dialog').close();view='all';feedScope='mine';category='all';$('#search').value='';$('#district').value='';document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('selected',b.dataset.category==='all');b.setAttribute('aria-pressed',b.dataset.category==='all')});render();toast('Listing saved locally. It is not publicly published.')};render();

function updateAccount(){const profile=currentProfile();$('#account').textContent=profile?profile.name:'Register / Sign in';$('#listing-owner').textContent=profile?`Listing as ${profile.name} · ${profile.role}`:'';$('#account-status').textContent=profile?`Local preview signed in as ${profile.name}. Not a verified account.`:'You are not signed in.';$('#signout').hidden=!profile}
function openAccount(){const select=$('#signin-profile');select.innerHTML='<option value="">Choose your registered demo profile</option>'+profiles.map(p=>`<option value="${safe(p.id)}">${safe(p.name)} · ${safe(p.role)}</option>`).join('');updateAccount();$('#account-dialog').showModal()}
function requestListing(){if(!currentProfile()){pendingListing=true;openAccount();return}updateAccount();const role=currentProfile().role;$('#form-category').value=({'Farmer':'produce','Wholesale buyer':'buyers','Transport provider':'transport','Fertilizer supplier':'supplies','Land seller':'land','Exporter':'export','Equipment seller':'equipment'})[role];$('#form-intent').value=['Wholesale buyer','Exporter'].includes(role)?'request':'offer';$('#listing-phone').value=currentProfile().phone||'';updateCatalogForm();$('#listing-dialog').showModal()}
function finishSignIn(id){currentProfileId=id;feedScope='recommended';view='all';category='all';$('#search').value='';$('#district').value='';$('#account-dialog').close();render();if(pendingListing){pendingListing=false;requestListing()}}
$('#account').onclick=()=>{pendingListing=false;openAccount()};
$('#signout').onclick=()=>{currentProfileId=null;feedScope='recommended';pendingListing=false;$('#listing-dialog').close();$('#account-dialog').close();render();toast('Signed out of the local preview.')};
$('#register-form').onsubmit=e=>{e.preventDefault();if(!e.target.reportValidity())return;const data=Object.fromEntries(new FormData(e.target));const name=data.name.trim(),phone=data.phone.replace(/^0/,'+94');if(!name||!data.wholesale||!districts.includes(data.district)||!/^\+94[0-9]{9}$/.test(phone)){toast('Complete your profile and accept wholesale-only trading.');return}if(profiles.some(p=>p.phone===phone)){toast('This number is already registered locally. Choose your profile below.');return}const profile={id:crypto.randomUUID(),name,phone,role:data.role,district:data.district,createdAt:new Date().toISOString(),wholesaleAcceptedAt:new Date().toISOString()};const next=[...profiles,profile];try{localStorage.setItem('fd-profiles-v1',JSON.stringify(next))}catch{toast('Registration could not be saved. Please enable browser storage.');return}profiles=next;e.target.reset();finishSignIn(profile.id);toast('Local profile registered. You can now create wholesale listings.')};
$('#signin-form').onsubmit=e=>{e.preventDefault();const id=$('#signin-profile').value;if(!profiles.some(p=>p.id===id)){toast('Choose a registered local profile.');return}finishSignIn(id)};

$('#feed-scope').onchange=()=>{feedScope=$('#feed-scope').value;category='all';render()};

function biddingEligible(listing){return listing&&listing.category==='produce'&&listing.intent==='offer'&&listing.authorRole==='Farmer'}
function bidTypeFor(profile,listing){if(!profile||!biddingEligible(listing)||profile.id===listing.profileId)return null;if(['Wholesale buyer','Exporter'].includes(profile.role))return 'buyer';if(profile.role==='Transport provider')return 'transport';return null}
function submitBid(listingId,input){const listing=all().find(x=>x.id===listingId),profile=currentProfile(),type=bidTypeFor(profile,listing);if(!type)return {ok:false,message:'Sign in with an eligible buyer or transport profile to bid.'};const amount=Number(input.amount),quantity=String(input.quantity||'').trim(),terms=String(input.terms||'').trim();if(!Number.isFinite(amount)||amount<=0||Math.abs(Math.round(amount*100)-amount*100)>0.000001||amount>1000000000||!quantity||quantity.length>120||!terms||terms.length>1000)return {ok:false,message:'Enter a valid amount, quantity or load, and bid terms.'};const next={id:crypto.randomUUID(),listingId,type,profileId:profile.id,bidder:profile.name,role:profile.role,amount,quantity,terms,updatedAt:new Date().toISOString()};const existing=state.bids.findIndex(b=>b.listingId===listingId&&b.profileId===profile.id&&b.type===type);if(existing>=0){next.id=state.bids[existing].id;state.bids[existing]=next}else state.bids.unshift(next);return {ok:true,persisted:persist()}}
function biddingHtml(listing){if(!biddingEligible(listing))return '';const profile=currentProfile(),type=bidTypeFor(profile,listing);const lane=(kind,title)=>{const bids=state.bids.filter(b=>b.listingId===listing.id&&b.type===kind).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return `<section class="bid-lane"><h3>${title}</h3><p class="muted">${kind==='buyer'?'Offers to purchase produce. Total price for the stated quantity.':'Quotes to transport produce. Total transport cost for the stated load.'}</p>${bids.length?bids.map(b=>`<article class="bid-row"><strong data-no-translate>${safe(b.bidder)}</strong><span>${safe(b.role)}</span><b data-no-translate>LKR ${Number(b.amount).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2})}</b><p data-no-translate>${safe(b.quantity)}</p><p data-no-translate>${safe(b.terms)}</p><time data-no-translate datetime="${safe(b.updatedAt)}">${safe(new Date(b.updatedAt).toLocaleString('en-GB',{timeZone:'Asia/Colombo'}))} (Sri Lanka)</time></article>`).join(''):'<p class="muted">No bids yet. Be the first to bid.</p>'}</section>`};return `<section class="bidding"><p class="eyebrow">OPEN BIDDING</p><h2>Buyer bids & transport quotes</h2><p class="muted">All bids on this device are visible here. This demo does not share bids between users or devices. Latest bid per bidder is shown. No winner or payment is automatic.</p>${lane('buyer','Buyer bids')}${lane('transport','Transport bids')}${type?`<form id="bid-form"><h3>${type==='buyer'?'Place a buyer bid':'Place a transport bid'}</h3><p class="muted">Your name, role, amount and terms will be visible on this local bid board.</p><label>Total amount (LKR)<input type="number" name="amount" required min="0.01" step="0.01" max="1000000000"></label><label>${type==='buyer'?'Quantity to purchase':'Load and route covered'}<input name="quantity" required maxlength="120"></label><label>Bid terms<textarea name="terms" required maxlength="1000" rows="3"></textarea></label><button class="primary">Submit / update open bid</button></form>`:`<p class="muted">${profile&&profile.id===listing.profileId?'You own this listing. Review buyer bids and transport quotes here.':'Sign in as a wholesale buyer, exporter or transport provider to bid.'}</p>`}</section>`}
function bindBidding(listing){if(!biddingEligible(listing)||!$('#bid-form'))return;$('#bid-form').onsubmit=event=>{event.preventDefault();const result=submitBid(listing.id,Object.fromEntries(new FormData(event.target)));if(!result.ok){toast(result.message);return}showDetail(listing.id);if(result.persisted)toast('Open bid saved locally. Not sent to other devices.')};}

function updateCatalogForm(){const produce=$('#form-category').value==='produce'&&$('#form-intent').value==='offer';$('#produce-price-fields').hidden=!produce;for(const key of ['#produce-price-amount','#produce-price-basis']){$(key).disabled=!produce;$(key).required=produce}const show=$('#form-category').value==='supplies'&&$('#form-intent').value==='offer';$('#fertilizer-fields').hidden=!show;for(const field of ['#pack-size']){$(field).required=show;$(field).disabled=!show}$('#catalog-type').disabled=!show}
$('#form-category').addEventListener('change',updateCatalogForm);$('#form-intent').addEventListener('change',updateCatalogForm);
function fertilizerGroups(rows,cardHtml){return [['product','Fertilizer products'],['offer','Fertilizer offers'],['request','Farmer fertilizer requests']].map(([type,title])=>{const matches=rows.filter(x=>type==='request'?x.intent==='request':x.intent==='offer'&&(x.catalogType||'product')===type);return matches.length?`<div class="catalog-group"><h3>${title}</h3><div class="section-listings">${matches.map(cardHtml).join('')}</div></div>`:''}).join('')}

function validateListingFields(fields){if(!categories.slice(1).some(c=>c[0]===fields.category)||!['offer','request'].includes(fields.intent))return 'Please complete each field.';for(const key of ['title','minimum','price','description','quality','unit','location','phone','district'])if(!String(fields[key]||'').trim())return 'Please complete each field.';if(!districts.includes(fields.district)||!Number.isFinite(Number(fields.quantity))||Number(fields.quantity)<=0||! /^(?:0[0-9]{9}|\+94[0-9]{9})$/.test(fields.phone))return 'Enter a valid quantity and Sri Lankan phone number.';if(fields.category==='produce'&&fields.intent==='offer'&&(!Number.isFinite(Number(fields.priceAmount))||Number(fields.priceAmount)<=0||!['kg','tonne','bag','unit'].includes(fields.priceBasis)))return 'Enter a positive unit price and select its unit.';if(fields.category==='supplies'&&fields.intent==='offer'&&!fields.packSize?.trim())return 'Enter pack size and available quantity.';return null}
function listingFactsHtml(x){const fact=(name,value)=>value?`<div><dt>${name}</dt><dd data-no-translate>${safe(value)}</dd></div>`:'';return `${x.images?.length?`<div class="listing-gallery">${x.images.map((image,index)=>`<img src="${safe(image)}" alt="${safe(x.title)} ${index+1}" loading="lazy">`).join('')}</div>`:''}<dl class="listing-facts">${fact('Quality / grade / condition',x.quality)}${fact('Quantity available',x.quantity?`${x.quantity} ${x.unit||''}`:null)}${fact('Town / village / pickup location',x.location)}${x.phone&&/^(?:0[0-9]{9}|\+94[0-9]{9})$/.test(x.phone)?`<div><dt>Contact phone number</dt><dd><a data-no-translate href="tel:${safe(x.phone)}">${safe(x.phone)}</a></dd></div>`:''}</dl>`}
function renderImagePreviews(){$('#image-previews').innerHTML=pendingImages.map((image,index)=>`<div><img src="${safe(image)}" alt="${index+1}"><button type="button" data-remove-image="${index}">Remove image</button></div>`).join('')}
async function compressListingImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Choose JPEG, PNG or WebP images under 5 MB each.');const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read image.'));reader.readAsDataURL(file)});const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Unable to read image.'));img.src=source});const scale=Math.min(1,1000/image.width,1000/image.height);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let encoded=canvas.toDataURL('image/jpeg',0.72);if(encoded.length>400000)encoded=canvas.toDataURL('image/jpeg',0.4);if(encoded.length>500000)throw Error('Image is too large after resizing. Choose a smaller image.');return encoded}
$('#listing-images').onchange=async event=>{if(processingImages)return;const files=[...event.target.files];if(files.length+pendingImages.length>5){toast('You can add up to 5 images.');event.target.value='';return}processingImages=true;try{const additions=[];for(const file of files)additions.push(await compressListingImage(file));pendingImages.push(...additions);renderImagePreviews()}catch(error){toast(error.message)}finally{processingImages=false;event.target.value=''}};
document.addEventListener('click',event=>{const button=event.target.closest('[data-remove-image]');if(button&&!processingImages){pendingImages.splice(Number(button.dataset.removeImage),1);renderImagePreviews()}});
